      "fTerm": "MODIFYING THE PHYSICAL STRUCTURE OF FERROUS METALS; GENERAL DEVICES FOR HEAT TREATMENT OF FERROUS OR NON-FERROUS METALS OR ALLOYS; MAKING METAL MALLEABLE, e.g. BY DECARBURISATION OR TEMPERING (cementation by diffusion processes <b>C23C</b>; surface treatment of metallic material involving at least one process provided for in class <b>C23</b> and at least one process covered by this subclass <b>C23F 17/00</b>; unidirectional solidification of eutectic materials or unidirectional demixing of eutectoid materials <b>C30B</b>)<br><br><b><u>Note(s)</u></b><br><br><ul type=\"\"1\"\"><li>Cementation by diffusion processes is classified in <b>C23C</b>.<b>[2012.01]</b></li><li>Surface treatments of metallic material involving at least one process provided for in class <b>C23</b> and at least one process covered by this subclass are classified in group <b>C23F 17/00</b>.</li></ul><br><br><b><u>Subclass indexes</u></b><br><table width=\"100%\"><tr><td width=\"70%\"><p style=\"\"text-indent:1em;margin:0\"\">HEAT TREATMENT</td><tr><td width=\"70%\"><p style=\"\"text-indent:2em;margin:0\"\">General methods or devices</td><td><b>1/00</b>, <b>11/00</b></td></p></tr><tr><td width=\"70%\"><p style=\"\"text-indent:2em;margin:0\"\">of cast-iron, of iron alloys</td><td><b>5/00</b>, <b>6/00</b></td></p></tr><tr><td width=\"70%\"><p style=\"\"text-indent:2em;margin:0\"\">adapted for particular articles</td><td><b>9/00</b></td></p></tr></p></tr><tr><td width=\"70%\"><p style=\"\"text-indent:1em;margin:0\"\">MECHANICAL TREATMENT</td><td><b>7/00</b></td></p></tr><tr><td width=\"70%\"><p style=\"\"text-indent:1em;margin:0\"\">COMBINED MECHANICAL AND THERMAL TREATMENTS</td><td><b>8/00</b></td></p></tr><tr><td width=\"70%\"><p style=\"\"text-indent:1em;margin:0\"\">OTHER TREATMENTS</td><td><b>10/00</b></td></p></tr><tr><td width=\"70%\"><p style=\"\"text-indent:1em;margin:0\"\">DIFFUSION PROCESSES FOR EXTRACTION OF NON-METALS</td><td><b>3/00</b></td></p></tr></table>",
